                },
                "required": [
                  "claim",
                  "why_it_matters",
                  "source_url"
                ],
                "additionalProperties": false
              }
            },

            "practical_workflows": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "workflow": {"type": "string"},
                  "use_case": {"type": "string"},
                  "evidence_or_example": {"type": "string"},
                  "source_url": {"type": "string"}
                },
                "required": [
                  "workflow",
                  "use_case",
                  "evidence_or_example",
                  "source_url"
                ],
                "additionalProperties": false
              }
            },

            "recent_developments": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "development": {"type": "string"},
                  "date": {"type": ["string", "null"]},
                  "why_it_matters": {"type": "string"},
                  "source_url": {"type": "string"}
                },
                "required": [
                  "development",
                  "date",
                  "why_it_matters",
                  "source_url"
                ],
                "additionalProperties": false
              }
            },

            "risks_and_limitations": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "risk": {"type": "string"},
                  "implication": {"type": "string"},
