                },
                "required": [
                  "risk",
                  "implication",
                  "source_url"
                ],
                "additionalProperties": false
              }
            },

            "counterarguments": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "argument": {"type": "string"},
                  "assessment": {"type": "string"},
                  "source_url": {"type": "string"}
                },
                "required": [
                  "argument",
                  "assessment",
                  "source_url"
                ],
                "additionalProperties": false
              }
            },

            "community_observations": {
              "type": "array",
