parameters.jsCode:
const response = $json;

const raw = response.choices?.[0]?.message?.content;

if (!raw) {
  throw new Error('No Deep Research content found in OpenRouter response');
}

let cleaned = raw
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let research;

try {
  research = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `Could not parse Deep Research JSON: ${error.message}`
  );
}

return {
  json: {
    research_summary: research.research_summary || "",
    verified_claims: research.verified_claims || [],
    practical_workflows: research.practical_workflows || [],
    recent_developments: research.recent_developments || [],
    risks_and_limitations: research.risks_and_limitations || [],
    counterarguments: research.counterarguments || [],
    community_observations: research.community_observations || [],
    unresolved_claims: research.unresolved_claims || [],
    recommended_article_evidence:
      research.recommended_article_evidence || [],

    research_meta: {
      model: response.model || "",
      total_tokens: response.usage?.total_tokens ?? null,
      research_cost: response.usage?.cost ?? null,
      web_search_requests:
        response.usage?.server_tool_use_details?.web_search_requests ?? null
    }
  }
};

const response = $json;

const raw = response.choices?.[0]?.message?.content;

if (!raw) {
  throw new Error('No outline content found in OpenRouter response');
}

let cleaned = raw
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let outline;

try {
  outline = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `Could not parse Outline JSON: ${error.message}`
  );
}

return {
  json: {
    working_title: outline.working_title || "",
    article_thesis: outline.article_thesis || "",
    reader_takeaway: outline.reader_takeaway || "",
    narrative_arc: outline.narrative_arc || "",
    sections: outline.sections || [],
    product_connection: outline.product_connection || {},
    conclusion_direction: outline.conclusion_direction || "",
    cta_direction: outline.cta_direction || "",

    outline_meta: {
      model: response.model || "",
      total_tokens: response.usage?.total_tokens ?? null,
      outline_cost: response.usage?.cost ?? null
    }
  }
};

const outline = $json;

// Original approved strategy/context
const strategy = $('Prepare Deep Research Brief').item.json;

const audience =
  typeof strategy.article_audience === 'string'
    ? JSON.parse(strategy.article_audience)
    : strategy.article_audience;

const contentObjective =
  strategy['Content objective'] ||
  strategy.content_objective ||
  "";

return {
  json: {
    article_strategy: {
      topic: strategy.Topic || "",
      primary_keyword: strategy['Primary Keyword'] || "",
      search_intent: strategy.Intent || "",
      content_objective: contentObjective,
      product_relevance: strategy['Product relevance'] || "",
      editorial_angle: strategy.Angle || "",
      audience: audience || {},
      core_argument: strategy.core_argument || "",
      unique_pov: strategy.unique_pov || ""
    },

    outline: {
      working_title: outline.working_title || "",
      article_thesis: outline.article_thesis || "",
      reader_takeaway: outline.reader_takeaway || "",
      narrative_arc: outline.narrative_arc || "",
      sections: outline.sections || [],
      product_connection: outline.product_connection || {},
      conclusion_direction: outline.conclusion_direction || "",
      cta_direction: outline.cta_direction || ""
    },

    writer_guardrails: {
  search_intent:
    "Search intent is the highest editorial priority. For informational queries, answer the primary question directly in the opening paragraphs. Explain the concept, how it works, its main types, examples, benefits, and limitations before discussing advanced applications. Do not turn an informational article into a tutorial, comparison, or product pitch.",

  outline:
    "Use the approved outline as the structural foundation, but apply editorial judgment to improve clarity and avoid repetition. Preserve its core argument, evidence, and useful insights. You may merge overlapping sections, shorten unnecessary explanations, or integrate minor sections into more relevant ones. Do not introduce unrelated topics.",

  memory_taxonomy:
    "When explaining AI memory types, distinguish between different classification dimensions. Short-term versus long-term describes how long context is retained. Semantic, episodic, and procedural describe what kind of information is remembered. These categories can overlap. Do not incorrectly present limited/session, episodic, and persistent memory as three mutually exclusive technical categories.",

  information_hierarchy:
    "Prioritize the reader's primary information need. For an article targeting 'what is ai memory', spend most of the article explaining AI memory itself. Memory portability should provide a distinctive perspective, not dominate the article. Keep practical portability recommendations concise and relevant.",

  section_structure:
    "Every section must introduce meaningful new information. Merge overlapping sections when appropriate. Avoid repeating explanations, workflows, examples, or recommendations. Prefer a concise, coherent article over unnecessary length.",

  evidence:
    "Use only evidence supplied in the outline for factual claims requiring external support. Do not invent sources, statistics, studies, product capabilities, or research findings. Treat cited research as material requiring accurate attribution, not as automatic proof that every claim is verified.",

  audience:
    "Write for the approved non-developer audience. Explain technical concepts in accessible, reader-facing language. Avoid unnecessary implementation details, developer tutorials, and infrastructure discussions.",

  product_truth:
    "AI Context Flow is a specific product positioned around an Open Context Layer. Do not infer product capabilities from the workflow, research, category, or article argument. Only make product claims explicitly established in the supplied input.",

  product_integration:
    "For informational articles, do not create a standalone promotional H2 section about AI Context Flow. Instead, integrate a brief, natural product reference near the end where it genuinely supports the reader's understanding. Keep the article useful without the product. Use a relevant, low-pressure CTA.",

  heuristics:
    "Clearly distinguish practical examples and editorial heuristics from evidence-backed claims. Do not present example numbers, time periods, thresholds, or rules of thumb as established research findings.",

  usefulness:
    "The article must provide standalone value even if the reader never uses AI Context Flow."
}
  }
};

const response = $json;

const raw = response.choices?.[0]?.message?.content;

if (!raw) {
  throw new Error('No article content found in OpenRouter response');
}

// Remove Markdown fences if present
const cleaned = raw
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let article;

try {
  article = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `Could not parse Article Draft JSON: ${error.message}`
  );
}

// Validate required fields
if (!article.title || !article.article_markdown) {
  throw new Error(
    'Article Draft is missing title or article_markdown'
  );
}

const markdown = article.article_markdown;

const wordCount = markdown
  .trim()
  .split(/\s+/)
  .filter(Boolean)
  .length;

return {
  json: {
    title: article.title,
    meta_description: article.meta_description || "",
    article_markdown: markdown,
    sources_used: article.sources_used || [],

    article_metrics: {
      word_count: wordCount,
      source_count: (article.sources_used || []).length,
      heading_count:
        (markdown.match(/^#{1,6}\s/gm) || []).length
    },

    writer_meta: {
      model: response.model || "",
      total_tokens: response.usage?.total_tokens ?? null,
      writing_cost: response.usage?.cost ?? null
    }
  }
};

const article = $json;

// Original approved strategy
const prepared = $('Prepare Article Writer').item.json;

const strategy = prepared.article_strategy;
const outline = prepared.outline;
const guardrails = prepared.writer_guardrails;

return {
  json: {
    article_strategy: strategy,

    approved_outline: {
      working_title: outline.working_title,
      article_thesis: outline.article_thesis,
      reader_takeaway: outline.reader_takeaway,
      narrative_arc: outline.narrative_arc,
      sections: outline.sections.map(section => ({
        heading: section.heading,
        purpose: section.purpose,
        key_points: section.key_points,
        evidence: section.evidence
      })),
      product_connection: outline.product_connection
    },

    article_draft: {
      title: article.title,
      meta_description: article.meta_description,
      article_markdown: article.article_markdown,
      sources_used: article.sources_used,
      metrics: article.article_metrics
    },

    editorial_guardrails: guardrails,

    qa_objectives: {
      search_intent_alignment:
        "Determine whether the article genuinely satisfies the original primary keyword and search intent. Detect when the article has drifted toward a different search query or article type.",

      strategy_fidelity:
        "Check whether the article preserves the approved audience, core argument, unique POV, content objective, and editorial angle.",

      factual_support:
        "Identify unsupported, exaggerated, misleading, or overly certain factual claims. Distinguish source-backed claims from practical recommendations.",

      source_integrity:
        "Check whether citations use only approved source URLs and whether each cited source is relevant to the claim. Flag claims that require independent verification. Do not assume a URL proves a claim merely because it appears in the approved outline.",

      product_truth:
        "Flag invented or unverified AI Context Flow capabilities, integrations, technical behavior, security guarantees, or performance claims.",

      audience_fit:
        "Check that the article remains useful and understandable for non-developer AI power users.",

      practical_value:
        "Evaluate whether templates, examples, checklists, and recommendations are actionable, internally consistent, and genuinely useful.",

      editorial_quality:
        "Identify repetition, generic AI prose, awkward keyword insertion, unnecessary technical detail, and weak narrative transitions.",

      publication_readiness:
        "Identify issues that must be resolved before human approval and WordPress publication."
    }
  }
};

const response = $json;

const raw = response.choices?.[0]?.message?.content;

if (!raw) {
  throw new Error('No Editorial QA content found');
}

const cleaned = raw
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let qa;

try {
  qa = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Editorial QA JSON parsing failed: ${error.message}`);
}

if (!['pass', 'revise', 'human_review'].includes(qa.decision)) {
  throw new Error(`Invalid QA decision: ${qa.decision}`);
}

// Keep the original article available for revision.
const prepared = $('Prepare Editorial QA').item.json;

return {
  json: {
    decision: qa.decision,
    summary: qa.summary || '',
    scores: qa.scores || {},
    issues: qa.issues || [],
    human_review_questions: qa.human_review_questions || [],
    revision_brief: qa.revision_brief || '',

    article_strategy: prepared.article_strategy,
    approved_outline: prepared.approved_outline,
    article_draft: prepared.article_draft,

    qa_meta: {
      model: response.model || '',
      total_tokens: response.usage?.total_tokens ?? null,
      qa_cost: response.usage?.cost ?? null
    }
  }
};

