  temperature: 0.2,
  messages: [
    {
      role: "system",
      content: `You are a senior editorial revision specialist.

Revise an existing article according to its editorial QA feedback.

Rules:
- Preserve the original article's factual claims, citations, and approved strategy.
- Resolve every major issue in the revision brief.
- Remove repetition and improve readability.
- Do not invent sources or product capabilities.
- Preserve the informational search intent.
- Keep AI Context Flow references neutral and accurate.
- Target 1200–1600 words for this article.
- Return valid JSON only, with:
  title, meta_description, article_markdown, revision_summary.`
    },
    {
      role: "user",
      content: JSON.stringify({
        original_article: $json.article_draft,
        revision_brief: $json.revision_brief,
        issues: $json.issues,
        article_strategy: $json.article_strategy,
        approved_outline: $json.approved_outline
      })
    }
  ]
})
}}

parameters.jsCode:
const source = $json;
if (source.decision !== 'pass') {
  throw new Error(`Article is not QA-passed: ${source.decision ?? 'missing decision'}`);
}
const article = source.article_draft;
if (!article || typeof article.title !== 'string' || !article.title.trim()) {
  throw new Error('Missing article_draft.title');
}
if (typeof article.article_markdown !== 'string' || !article.article_markdown.trim()) {
  throw new Error('Missing article_draft.article_markdown');
}
const title = article.title.trim();
const packageText = [
  `# ${title}`,
  'Review status: Pending human approval. This memory is a review package, not an approved or published article.',
  `Meta description: ${article.meta_description || ''}`,
  '## Full article Markdown',
  article.article_markdown,
  '## Sources used',
  JSON.stringify(article.sources_used ?? [], null, 2),
  '## Editorial QA',
  JSON.stringify({
    decision: source.decision,
    summary: source.summary ?? '',
    scores: source.scores ?? {},
    issues: source.issues ?? [],
    human_review_questions: source.human_review_questions ?? [],
    revision_brief: source.revision_brief ?? ''
  }, null, 2),
  '## Article strategy',
  JSON.stringify(source.article_strategy ?? {}, null, 2),
  '## Approved outline',
  JSON.stringify(source.approved_outline ?? {}, null, 2)
].join('\n\n');
return {
  json: {
    ...source,
    plurality_review: {
      profile_id: 'REPLACE_WITH_YOUR_REVIEW_BUCKET_ID',
      title: `Review: ${title}`,
      content: packageText,
      source_platform: 'n8n'
    }
  }
};

